// Source is the activity_source name of Garmin Connect activity IDs.
const Source = "garmin"

// overlap re-reads recent days on every sync so renames in Garmin Connect
// and late uploads are picked up.
const overlap = 7 * 24 * time.Hour

// Setting keys of the persisted sync state.
const (
	settingLastSync  = "garmin.last_sync"
	settingLastState = "garmin.last_state"
)

// State is the persisted result of the last sync, shown in the panel.
type State struct {
	At         time.Time `json:"at"`
	OK         bool      `json:"ok"`
	Error      string    `json:"error,omitempty"`
	NeedsLogin bool      `json:"needs_login,omitempty"`
	Listed     int       `json:"listed"`
	Imported   int       `json:"imported"`
	Known      int       `json:"known"`
	NoFile     int       `json:"no_file"`
	Renamed    int       `json:"renamed"`
	// HealthDays counts the days of health values updated; HealthError
	// is set if only the health part failed.
	HealthDays  int    `json:"health_days,omitempty"`
	HealthError string `json:"health_error,omitempty"`
}

// Syncer imports new Garmin Connect activities.
type Syncer struct {
	Client   *Client
	Importer *importer.Importer
	Store    *store.Store
	// Since is the first day of the initial backfill.
	Since time.Time
	// Delay between downloads, to stay well below any rate limit.
	Delay  time.Duration
	Now    func() time.Time
	Logger *slog.Logger
}

func (s *Syncer) now() time.Time {
	if s.Now != nil {
		return s.Now()
	}
	return time.Now()
}

func (s *Syncer) logger() *slog.Logger {
	if s.Logger != nil {
		return s.Logger
	}
	return slog.New(slog.DiscardHandler)
}

// from returns the first day to list: the backfill start on the first run,
// afterwards the last successful sync minus the overlap.
func (s *Syncer) from(ctx context.Context) time.Time {
	from := s.Since
	if v, ok, err := s.Store.Setting(ctx, settingLastSync); err == nil && ok {
		if last, err := time.Parse(time.RFC3339, v); err == nil {
			if d := last.Add(-overlap); d.After(from) {
				from = d
			}
		}
	}
	return from
}

// Run lists Garmin Connect activities, downloads the unknown ones as
// original FIT files and imports them. Every imported file is reported to
// report (the panel shows them like a manual import).
func (s *Syncer) Run(ctx context.Context, report func(importer.Result)) (State, error) {
	state := State{At: s.now().UTC()}
	runErr := s.run(ctx, &state, report)
	s.finish(ctx, &state, runErr)
	return state, runErr
}

func (s *Syncer) run(ctx context.Context, state *State, report func(importer.Result)) error {
	keys, err := s.Store.SourceKeys(ctx, Source)
	if err != nil {
		return err
	}
	known := make(map[string]bool, len(keys))
	for _, k := range keys {
		known[k] = true
	}
	since := s.from(ctx)
	s.logger().Info("garmin sync started", "since", since.Format(time.DateOnly), "known", len(known))

	list, err := s.Client.Activities(ctx, since)
	if err != nil {
		return err
	}
	state.Listed = len(list)
	// Oldest first, so an interrupted backfill resumes in order.
	for i := len(list) - 1; i >= 0; i-- {
		act := list[i]
		id := strconv.FormatInt(act.ID, 10)
		if act.ID <= 0 {
			continue
		}
		if known[id] {
			state.Known++
			if changed, err := s.Store.SetSourceTitle(ctx, Source, id, act.Name); err == nil && changed {
				state.Renamed++
			}
			continue
		}
		res, err := s.importActivity(ctx, act)
		if errors.Is(err, ErrNoFile) {
			state.NoFile++
			continue
		}
		if err != nil {
			return err
		}
		if res.Status != importer.StatusFailed {
			state.Imported++
		}
		if report != nil {
			report(res)
		}
		if s.Delay > 0 {
			select {
			case <-ctx.Done():
				return ctx.Err()
			case <-time.After(s.Delay):
			}
		}
	}
	return s.syncHealth(ctx, state)
}

// importActivity downloads one activity, imports it and links its Garmin ID.
// Download errors other than ErrNoFile abort the sync (auth, rate limit).
func (s *Syncer) importActivity(ctx context.Context, act Activity) (importer.Result, error) {
	id := strconv.FormatInt(act.ID, 10)
	data, err := s.Client.DownloadFIT(ctx, act.ID)
	if err != nil {
		return importer.Result{}, err
	}
	res := s.Importer.ImportReader(ctx, bytes.NewReader(data), "garmin:"+id)
	if res.Status == importer.StatusFailed || res.Status == importer.StatusSkipped {
		s.logger().Warn("garmin import failed", "activity", id, "status", res.Status, "err", res.Error)
		return res, nil
	}
	if err := s.Store.AttachSource(ctx, res.ActivityID, Source, id, act.Name); err != nil {
		s.logger().Warn("link garmin activity", "activity", id, "err", err)
	}
	return res, nil
}

func (s *Syncer) finish(ctx context.Context, state *State, runErr error) {
	state.OK = runErr == nil
	if runErr != nil {
		state.Error = runErr.Error()
		state.NeedsLogin = errors.Is(runErr, ErrAuthRequired)
	} else if err := s.Store.SetSetting(ctx, settingLastSync, state.At.Format(time.RFC3339)); err != nil {
		s.logger().Error("store last sync", "err", err)
	}
	b, _ := json.Marshal(state)
	if err := s.Store.SetSetting(ctx, settingLastState, string(b)); err != nil {
		s.logger().Error("store sync state", "err", err)
	}
	s.logger().Info("garmin sync finished", "ok", state.OK, "listed", state.Listed, "imported", state.Imported,
		"known", state.Known, "renamed", state.Renamed, "health_days", state.HealthDays, "health_err", state.HealthError, "err", state.Error)
}

// LastState returns the result of the last sync, or nil before the first one.
func LastState(ctx context.Context, st *store.Store) (*State, error) {
	v, ok, err := st.Setting(ctx, settingLastState)
	if err != nil || !ok {
		return nil, err
	}
	var state State
	if err := json.Unmarshal([]byte(v), &state); err != nil {
		return nil, fmt.Errorf("decode sync state: %w", err)
	}
	return &state, nil
}
